namespace CloudServer; public partial class App : System.Windows.Application { readonly CancellationTokenSource apiCancellation=new(); protected override void OnStartup(System.Windows.StartupEventArgs e){base.OnStartup(e);var store=new StateStore();if(store.State.Users.Count==0){var setup=new FirstRunWindow();if(setup.ShowDialog()!=true){Shutdown();return;}store.State.Users.Add(new UserAccount{UserName=setup.UserName,DisplayName=setup.DisplayName,IsAdmin=true,PasswordHash=StateStore.Hash(setup.Password),QuotaBytes=0});store.Save();}var admin=new AdminWindow(store);admin.Show();admin.SetApiStarting();System.Threading.Tasks.Task.Run(()=>Api.Run(store,apiCancellation.Token,()=>Dispatcher.Invoke(admin.SetApiStarted))).ContinueWith(t=>{if(t.IsFaulted)Dispatcher.Invoke(()=>admin.SetApiStatus(t.Exception?.GetBaseException()));else if(!apiCancellation.IsCancellationRequested)Dispatcher.Invoke(()=>admin.SetApiStatus(null));},System.Threading.Tasks.TaskScheduler.Default);} protected override void OnExit(System.Windows.ExitEventArgs e){apiCancellation.Cancel();apiCancellation.Dispose();base.OnExit(e);} }